/*
 * BasePage — base class for all Zimmermann Page Objects.
 *
 * Selector priority (enforced by code review):
 *   1. data-testid  — preferred, stable across refactors
 *   2. ARIA role    — accessible label, survives copy changes
 *   3. CSS selector — last resort only, document the reason in a comment
 *
 * Do not use raw selectors in test files — always go through a Page Object method.
 */

const { expect, errors } = require('@playwright/test');
const { RETAIL_APP_HOME } = require('../../config');

// Consent state (declined or already-recorded) persists for the life of a
// browser context once dismissConsent() has run there once — Didomi records
// the decision client-side, so a second navigation in the same context never
// shows the dialog again. Without this cache, every goto() after the first
// pays the full 10s dismissConsent() timeout for a dialog that will never
// appear.
const consentHandledContexts = new WeakSet();

class BasePage {
  constructor(page) {
    this.page = page;
  }

  // Some non-production RETAIL_APP_HOME targets (e.g. an access-gated MRT
  // preview URL) require a custom header to reach at all. Optional and
  // off by default — SIT/production targets need neither var set. Not
  // Didomi-specific; a generic single header pair, since that's the one
  // real case this repo has needed so far.
  async applyExtraHeaders() {
    const name = process.env.E2E_EXTRA_HEADER_NAME;
    const value = process.env.E2E_EXTRA_HEADER_VALUE;
    if (name && value) {
      await this.page.setExtraHTTPHeaders({ [name]: value });
    }
  }

  async goto(path = '') {
    await this.applyExtraHeaders();
    const response = await this.page.goto(`${RETAIL_APP_HOME}${path}`);
    // 'networkidle' timed out against the real dev environment — this app
    // never goes fully network-idle (analytics, consent tooling, etc.), same
    // reason Playwright's own docs discourage relying on it. Every other
    // Page Object method here already uses the default 'load' state via a
    // bare waitForLoadState() call; goto() was the only outlier.
    await this.page.waitForLoadState();
    await this.dismissConsent();
    return response;
  }

  // Didomi's consent dialog is a true aria-modal="true" dialog on first visit
  // (no consent cookie yet in a fresh test browser context) — while it's
  // open, the rest of the page is inert to the accessibility tree, so every
  // getByRole() query against header/nav/content fails until it's dismissed.
  // Confirmed against the real dev environment: AGENTS.md > Consent &
  // Marketing's "fail closed on consent" behaviour extends to blocking
  // interaction with the rest of the page, not just gating third-party
  // scripts. Declines rather than accepts — no reason for CI/bot traffic to
  // opt into tracking.
  //
  // Didomi loads its banner asynchronously and its render time varies by
  // environment — near-instant against a warmed, minified deployed bundle,
  // several seconds against an unminified local dev-server bundle. An
  // instant .count() check races this and silently does nothing on a slow
  // render, leaving the dialog to block the rest of the test later. Wait
  // for it (bounded) instead, and treat a timeout as "no dialog appeared"
  // (e.g. consent already recorded) rather than an error.
  async dismissConsent() {
    const context = this.page.context();
    if (consentHandledContexts.has(context)) return;

    const dialog = this.page.locator('[aria-modal="true"]');
    try {
      await dialog.waitFor({ state: 'visible', timeout: 10000 });
    } catch (error) {
      if (error instanceof errors.TimeoutError) {
        consentHandledContexts.add(context); // No dialog this time — won't appear again this context either.
        return;
      }
      throw error;
    }
    // Outside the try/catch: a real click failure must propagate rather than
    // be swallowed as "no dialog appeared", which would let goto() continue
    // with the modal still blocking the rest of the page.
    //
    // The decline button's accessible name is locale-translated ("Decline
    // tracking" only in English — "Refuser le suivi" on fr-eu, etc.), so
    // matching by name silently breaks on every non-English site (confirmed
    // against fr-eu: this left the dialog open, which per the note above
    // makes the rest of the page inert to the accessibility tree, timing out
    // every subsequent locator). No locale-independent id/data-testid exists
    // on this dialog. The modal's close (X) button lives outside
    // .chakra-modal__body, so scoping there doesn't collide with it — but
    // .chakra-modal__body renders TWO duplicate decline/accept button pairs
    // (a responsive mobile/desktop pair, both present in the DOM; confirmed
    // on fr-eu the first pair in DOM order is the hidden one, so plain
    // `.first()` grabbed a non-interactable element and hung until timeout).
    // `:visible` (a Playwright selector extension, not standard CSS) filters
    // to the interactable pair regardless of which one is first in the DOM;
    // decline still precedes accept within a visible pair, so `.first()`
    // after that lands on decline. CSS/structural selector, last resort per
    // this file's own selector-priority doc above, used because no more
    // specific option exists.
    //
    // [aria-modal="true"] matches ANY modal, not specifically this consent
    // dialog — there's no window.Didomi global or Didomi-native DOM to scope
    // to instead (confirmed: this app renders consent as its own Chakra
    // modal, not Didomi's widget). If some other aria-modal dialog were ever
    // open at the same time, blindly clicking "first visible button" could
    // hit the wrong control. Guard against that: only proceed when the
    // matched dialog has exactly the decline+accept pair this method expects
    // (2 visible buttons in .chakra-modal__body) — anything else fails loudly
    // rather than risk clicking an unrelated dialog's action.
    const visibleButtons = dialog.locator('.chakra-modal__body button:visible');
    const visibleCount = await visibleButtons.count();
    if (visibleCount !== 2) {
      throw new Error(
        `dismissConsent: expected exactly 2 visible buttons (decline/accept) in the ` +
          `aria-modal dialog, found ${visibleCount} — this may not be the consent dialog`,
      );
    }
    await visibleButtons.first().click();
    // Wait for the close animation to actually finish, not just the click
    // to register — Chakra's modal exit transition can leave the dialog
    // technically still 'visible' (mid fade-out) for a beat after decline
    // is clicked. Without this, a caller that immediately checks for
    // another dialog (e.g. MobileDrawerMenuPage opening the hamburger
    // drawer) can catch this one still present and match two dialogs
    // instead of one — confirmed as a real, intermittent failure mode
    // (2026-08-25), not hypothetical.
    await dialog.waitFor({ state: 'hidden' });
    consentHandledContexts.add(context);
  }

  async waitForVisible(locator) {
    await expect(locator).toBeVisible();
  }

  async waitForUrl(urlPattern) {
    await this.page.waitForURL(urlPattern);
  }

  // Use waitForResponse instead of waitForTimeout for SFCC API calls
  async waitForApiResponse(urlPattern) {
    return this.page.waitForResponse((response) => response.url().includes(urlPattern) && response.status() === 200);
  }
}

module.exports = { BasePage };

