/*
 * Hand-maintained fixture-key -> URL-prefix map for E2E site-routing tests.
 *
 * site.js (SITE_CONFIGS) does not carry URL-prefix data — it only tracks
 * siteId/locale/currency, derived from live SFCC data via
 * `npm run sync:regional-config`. The URL prefix ('urlSlug') is a routing
 * concept owned by overrides/app/config/countries.ts, keyed by the slug
 * itself rather than this fixture's camelCase keys — this file bridges that
 * gap without hand-editing the auto-generated site fixture.
 *
 * Keep in sync with overrides/app/config/countries.ts's COUNTRIES export.
 * Verified directly against the live dev environment (2026-08-25): the
 * `?site=<key>` query override does NOT accept these fixture keys (e.g.
 * `?site=usIntl` silently falls back to `us`, not an error) — only a direct
 * path prefix (e.g. `/en-ca/`) reliably selects the intended site. These
 * urlPrefix values are for path-prefix navigation, not the `?site=` param.
 */
module.exports = {
  au: { urlPrefix: '' },
  us: { urlPrefix: '/us' },
  usIntl: { urlPrefix: '/en-ca' },
  uk: { urlPrefix: '/uk' },
  enEu: { urlPrefix: '/en-eu' },
  frEu: { urlPrefix: '/fr-eu' },
  itEu: { urlPrefix: '/it-eu' },
  esEu: { urlPrefix: '/es-eu' },
  euIntl: { urlPrefix: '/en-ch' },
  hk: { urlPrefix: '/hk' },
  me: { urlPrefix: '/en-ae' },
};

