=== ListMenuPage @ live ===
const { BasePage } = require('./BasePage');

class ListMenuPage extends BasePage {
  constructor(page) {
    super(page);
    // getByRole('navigation', {name: ...}) is not usable here: the base
    // SFCC list-menu component's aria-label is translated per locale
    // ("Main navigation" in English, "Navigation principale" in French —
    // confirmed against fr-eu), so an English-text match silently breaks
    // on every non-English site. Its id ("list-menu") is the base
    // component's own stable DOM anchor, independent of locale/translation.
    // CSS selector, last resort per BasePage's selector-priority doc, used
    // because no locale-independent ARIA/data-testid option exists.
    this.nav = page.locator('#list-menu');
  }

  async goToSite(urlPrefix) {
    return this.goto(urlPrefix ? `${urlPrefix}/` : '/');
  }

  // Desktop-only (#list-menu is hidden below the lg breakpoint) — see
  // MobileDrawerMenuPage for the separate mobile entry point, which is a
  // genuinely different component, not a responsive variant of this one.
  //
  // Only relative, path-based hrefs are in scope for a site-prefix check —
  // filters out any external/anchor/protocol links a future nav item might
  // add, rather than asserting on link types this test isn't about.
  async getNavLinkHrefs() {
    const links = this.nav.getByRole('link');
    await links.first().waitFor({ state: 'visible' });
    const hrefs = await links.evaluateAll((elements) => elements.map((el) => el.getAttribute('href')));
    return hrefs.filter((href) => href && href.startsWith('/'));
  }
}

module.exports = { ListMenuPage };

=== MobileDrawerMenuPage @ live ===
const { BasePage } = require('./BasePage');

// The mobile hamburger drawer is a genuinely different component from
// desktop's #list-menu (base SFCC drawer-menu vs list-menu) — not a
// responsive variant of the same one, and #list-menu stays hidden even
// after opening this drawer (confirmed 2026-08-25). Kept as its own Page
// Object rather than a mobile branch inside ListMenuPage for that reason.
class MobileDrawerMenuPage extends BasePage {
  constructor(page) {
    super(page);
    this.menuButton = page.getByRole('button', { name: 'Menu' });
  }

  async goToSite(urlPrefix) {
    return this.goto(urlPrefix ? `${urlPrefix}/` : '/');
  }

  // Bounded, explicit wait (not Playwright's full default 30s auto-wait) —
  // a real gap here should fail fast, not hang.
  async getDrawerLinkHrefs() {
    await this.menuButton.click();
    // ARIA role + accessible name ("Menu Drawer") — tier 2 per BasePage's
    // selector-priority doc, and specific enough to never collide with the
    // consent dialog even if it's still mid-close-animation (a real
    // strict-mode-violation failure this originally hit, 2026-08-25, before
    // switching from a generic '[role="dialog"]:visible' to this).
    const drawer = this.page.getByRole('dialog', { name: 'Menu Drawer' });
    await drawer.waitFor({ state: 'visible', timeout: 8000 });
    const hrefs = await drawer
      .locator('a[href]')
      .evaluateAll((elements) => elements.map((el) => el.getAttribute('href')));
    return hrefs.filter((href) => href && href.startsWith('/'));
  }
}

module.exports = { MobileDrawerMenuPage };

