=== buildPushEntries + push (switchEnv.mjs 317-375) ===
// Shared scope pushes just .env.shared. Tier scopes push the same
// shared+tier merge that ends up in a locally switched .env (see
// mergeSharedAndTier) — so a GitHub Environment bound to one tier is
// self-sufficient, and a CI job doesn't need a second environment binding
// just to see shared-scope values like the Commerce API short code / site
// id. Returns null if the required local file(s) don't exist yet.
function buildPushEntries(scope) {
  if (scope === 'shared') {
    const filePath = path.join(ROOT, '.env.shared');
    if (!fs.existsSync(filePath)) return null;
    return readEnvFile(filePath).filter(([, value]) => value);
  }
  const merged = mergeSharedAndTier(scope);
  if (!merged) return null;
  return [...merged.entries()].filter(([, value]) => value);
}

function pushToGitHubEnvironment(scope) {
  const sourceLabel = scope === 'shared' ? '.env.shared' : `.env.shared + .env.${scope}`;
  const allEntries = buildPushEntries(scope);
  if (!allEntries) {
    console.error(`${sourceLabel} doesn't exist yet — run \`npm run env -- init\` first.`);
    process.exit(1);
  }

  const { approved, login } = isTier1Approver();
  if (!approved) {
    console.log(
      `Authenticated as '${login}' — not a tier-1-approver. Only tier-1-approvers can push to GitHub Environments.`,
    );
    return;
  }

  // Personal-scope keys (present in .env.shared, merged in for tier pushes
  // too) never leave this machine — pushing your own Jira/CMA token would
  // put every teammate's actions under your identity.
  const entries = allEntries.filter(([key]) => !PERSONAL_KEYS.has(key));
  const skippedPersonal = allEntries.length - entries.length;
  if (skippedPersonal) {
    console.log(
      `Excluding ${skippedPersonal} personal-scope value(s) — these are never pushed: ${allEntries
        .filter(([key]) => PERSONAL_KEYS.has(key))
        .map(([key]) => key)
        .join(', ')}`,
    );
  }
  if (!entries.length) {
    console.log(`Nothing to push — ${sourceLabel} has no filled-in, push-eligible values yet.`);
    return;
  }

  const tempFile = path.join(os.tmpdir(), `.env.push-${scope}.tmp`);
  fs.writeFileSync(tempFile, entries.map(([key, value]) => `${key}=${value}`).join('\n') + '\n');
  try {
    execSync(`gh variable set -f "${tempFile}" --env ${scope}`, { stdio: 'inherit' });
    console.log(`Pushed ${entries.length} value(s) to the "${scope}" GitHub Environment.`);
  } finally {
    fs.unlinkSync(tempFile);
  }

